mapper.select:
SELECT * FROM payment

    
        AND student_id = #{studentId}
    
    
        AND pay_type = #{payType}
    
    
        AND pay_date >= #{startTime}
    
    
        AND pay_date <= #{endTime}
    
    
        AND pay_method = #{payMethod}
    
    
        AND status = #{status}
    

ORDER BY pay_date DESC
